import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { TimesheetEntryComponent } from './pages/timesheet-entry/timesheet-entry.component';
import { EmployeeDashboardComponent } from './pages/employee-dashboard/employee-dashboard.component';
import { MainComponent } from 'src/app/pages/main/main.component';

import { ProjectEmployeeMappingComponent } from './pages/project-employee-mapping/project-employee-mapping.component';
import { TimesheetApprovalsComponent } from './pages/timesheet-approvals/timesheet-approvals.component';
import { ManagerDashboardComponent } from './pages/manager-dashboard/manager-dashboard.component';

import { TaskAssignEmployeeComponent } from './pages/task-assign-employee/task-assign-employee.component';

import { ProjectSummaryReportSuperadminComponent } from './reports/project-summary-report-superadmin/project-summary-report-superadmin.component';
import { ProjectSummaryReportManagerComponent } from './reports/project-summary-report-manager/project-summary-report-manager.component';
import { EmployeeProjectSummaryReportComponent } from './reports/employee-project-summary-report/employee-project-summary-report.component';
import { TaskMasterComponent } from './master-screens/task-master/task-master.component';
import { ClientMasterComponent } from './master-screens/client-master/client-master.component';
import { ProjectMasterComponent } from './master-screens/project-master/project-master.component';
import { ProjectRoleConfigurationComponent } from './master-screens/project-role-configuration/project-role-configuration.component';
import { VarianceReportComponent } from './reports/variance-report/variance-report.component';
import { SuperAdminDashboardComponent } from './pages/super-admin-dashboard/super-admin-dashboard.component';

const routes: Routes = [
  {
    path:'',component:MainComponent,
    children:[
      { path: 'employee-dashboard', component:EmployeeDashboardComponent },
      { path: 'manager-dashboard', component:ManagerDashboardComponent },
      { path: 'client-master', component:ClientMasterComponent },
      { path: 'project-master', component:ProjectMasterComponent },
      { path: 'project-team', component:ProjectEmployeeMappingComponent },
      { path: 'task-master', component:TaskMasterComponent },
      { path: 'task-assign', component:TaskAssignEmployeeComponent },
      { path: 'project-roles', component:ProjectRoleConfigurationComponent },
     
      { path: 'timesheet-entry', component:TimesheetEntryComponent },
      { path: 'timesheet-approvals', component:TimesheetApprovalsComponent },
      { path: 'summaryreport-superadmin', component:ProjectSummaryReportSuperadminComponent },
      { path: 'summaryreport-manager', component:ProjectSummaryReportManagerComponent },
      { path: 'summaryreport-employee', component:EmployeeProjectSummaryReportComponent },
      { path: 'variance-report', component:VarianceReportComponent },
      { path: 'admin-dashboard', component:SuperAdminDashboardComponent },
       
      ]
  }
  
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class TimesheetRoutingModule { }
