import { Component, OnInit, ViewChild } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { TimesheetService } from '../../timesheet.service';
import { Router } from '@angular/router';
import { FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { MatSort } from '@angular/material/sort';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';



@Component({
  selector: 'app-task-assign-employee',
  templateUrl: './task-assign-employee.component.html',
  styleUrls: ['./task-assign-employee.component.scss']
})
export class TaskAssignEmployeeComponent implements OnInit {
  submittedData: any[] = [];
  constructor(
    private router: Router,
    private timesheetService: TimesheetService,
    private fb: FormBuilder,
    private snackbarService: CommonSnackbarService,
  ) {
  }
  userSession: any;
  taskAssignForm!: FormGroup;
  isAdd: boolean = false;
  viewMode: boolean = false;
  isdata: boolean = true;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = [
    'sno',
    'projectName',
    'task',
    'employees',
    'status',
    'action'
  ];
  statusList: string[] = ['Not Started', 'In Progress', 'Completed'];
  projectList: any = [];
  taskList: any = [];
  employeeList: any = [];

  selectedEmployees: any = [];
  selectedProjectId: any;
  selectedTaskId: any;
  isEdit: boolean = false;
  filteredProjects: any;
  projectSearch: any;
  projectSearchControl = new FormControl('');

  filteredTask: any;
  taskSearch: any;
  taskSearchControl = new FormControl('');
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.taskAssignForm = this.fb.group({
      projectName: ['', Validators.required],
      task: ['', Validators.required],
      employees: [''],
      status: ['', Validators.required],
    });
    this.getProjectList();
    this.getAssignedEmployeeList();
    this.taskAssignForm.get('projectName')?.valueChanges.subscribe((selectedValue: any) => {
      this.selectedProjectId = selectedValue;
      if(!this.isEdit) this.getTaskList(selectedValue);
    })

    this.taskAssignForm.get('task')?.valueChanges.subscribe((selectedValue: any) => {
      if(!this.isEdit) this.getEmployeeList(selectedValue);
    })
    this.projectSearchControl.valueChanges.subscribe((value) => {
      this.projectSearch = value;
      this.filterprojects()
    });

        this.taskSearchControl.valueChanges.subscribe((value) => {
      this.taskSearch = value;
      this.filterTasks()
    });
  }

  getProjectList() {
    this.projectList = [];
    this.filteredProjects = [];      
    this.timesheetService.getAllActiveProjects().subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        this.projectList = res.data;
        this.filteredProjects = [...this.projectList];
      }
    })
  }

  getTaskList(id: any) {
    this.taskList = [];
    this.filteredTask = [];
     if (id === null || id === undefined) {
    return;
   }
    this.timesheetService.getTaskListByProjectId(id).subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        this.taskList = res.data;
        this.filteredTask = [...this.taskList];
      }
    })
  }

  getEmployeeList(id: any) {
    this.employeeList = [];
    let data = {
      projectid: this.selectedProjectId,
      rmid: this.userSession.id,
      task_id_value: id,
    }
    this.timesheetService.getEmployeesForTaskAssignment(data).subscribe((res: any) => {
      this.employeeList = (res.status && res.data && res.data.length > 0) ?res.data:this.employeeList;   
    });
  }

  submit() {

    if (this.taskAssignForm.valid) {
      const payload = {
        id_value: null,
        project_id_value: this.taskAssignForm.get('projectName')?.value,
        task_id_value: this.taskAssignForm.get('task')?.value,
        empid_value: JSON.stringify(this.taskAssignForm.get('employees')?.value),
        mapping_status_value: this.taskAssignForm.get('status')?.value,
        action_by_value: this.userSession.id,
        edit_delete_flag: null
      };

      this.timesheetService.setTimesheetTaskAsign(payload).subscribe((res: any) => {
        if (res.status) {
          let value = res.data[0]
          if (value.successstate == 0) {
            let message = 'Data saved successfully'
            this.snackbarService.show(message, true);

          } else if (value.successstate == 1) {
            this.snackbarService.show('Record already exists.', false);

          } else if (value.successstate == 2) {
            this.snackbarService.show('Data updated successfully.', true);
          }
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["timesheet/task-assign"]));
        } else {
          this.snackbarService.show('Unable to save data.', false);
        }
      })
    } else {
      console.log("Form is invalid", this.taskAssignForm.errors);
    }
    this.taskAssignForm.markAllAsTouched();

  }

  Add() {
    this.taskAssignForm.reset();
    this.filteredProjects = [...this.projectList];
    this.filteredTask = [...this.taskList];
    this.isAdd = true;
    this.isdata = false;
     this.isEdit = false;
  }

  getAssignedEmployeeList() {
    this.timesheetService.getAssignedTasksEmployeeHistory().subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        let data = res.data;
        this.dataSource = new MatTableDataSource(data)
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })
  }

  editRow(data: any) {
    this.isAdd = true;
    this.isEdit = true;
    this.taskAssignForm.reset();
    this.selectedTaskId = data.id; 

    this.filteredProjects = [{id:data.project_id, project_name:data.project_name}];     
    this.taskAssignForm.get('projectName')?.setValue(this.filteredProjects[0].id);
    this.taskAssignForm.get('projectName')?.disable();
    
    this.filteredTask = [{id:data.task_id, taskname:data.task_name }];  
    this.taskAssignForm.get('task')?.setValue(this.filteredTask[0].id); 
    this.taskAssignForm.get('task')?.disable();   
    
    this.employeeList = [{empid: data.empid, empcode:data.emp_code, empname:data.emp_name}];  
    this.taskAssignForm.get('employees')?.setValue([this.employeeList[0].empid]);
    this.taskAssignForm.get('employees')?.disable();

    this.taskAssignForm.get('status')?.setValue(data.mapping_status);
    this.taskAssignForm.get('status')?.enable();
  }

  update() {
    if (this.taskAssignForm.valid) {
      const payload = {
        id_value: this.selectedTaskId,
        project_id_value: this.taskAssignForm.get('projectName')?.value,
        task_id_value: this.taskAssignForm.get('task')?.value,
        empid_value: JSON.stringify(this.taskAssignForm.get('employees')?.value),
        mapping_status_value: this.taskAssignForm.get('status')?.value,
        action_by_value: this.userSession.id,
        edit_delete_flag: 1
      };
      this.timesheetService.setTimesheetTaskAsign(payload).subscribe((res: any) => {
        if (res.status) {
          let value = res.data[0]
          if (value.successstate == 0) {
            this.snackbarService.show('Data saved successfully.', true);


          } else if (value.successstate == 1) {
            this.snackbarService.show('Record already exists.', false);

          } else if (value.successstate == 2) {
            this.snackbarService.show('Data updated successfully.', true);
          }
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["timesheet/task-assign"]));
        } else {
          this.snackbarService.show('Unable to save data.', false);
        }
      })
    } else {
      console.log("Form is invalid", this.taskAssignForm.errors);
    }
    this.taskAssignForm.markAllAsTouched();

  }

  dataDelete(data: any) {
    const payload = {
      id_value: data.id,
      project_id_value: data.project_id,
      task_id_value: data.task_id,
      empid_value: JSON.stringify(data.empid),
      mapping_status_value: data.mapping_status,
      action_by_value: this.userSession.id,
      edit_delete_flag: 2
    };
    this.timesheetService.setTimesheetTaskAsign(payload).subscribe((res: any) => {
      if (res.status) {
        let value = res.data[0]
        if (value.successstate == 2) {
          this.snackbarService.show('Record deleted successfully.', true);


        } else if (value.successstate == 1) {
          this.snackbarService.show('Some effort is already logged by this employee on this task, so task cannot be deleted.', false);

        }
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["timesheet/task-assign"]));
      } else {
        this.snackbarService.show('Unable to delete record.', false);
      }
    })
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/timesheet/task-assign"]));
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
  filterprojects(): any {
    if (this.projectSearch && this.projectSearch !='') {
      this.filteredProjects = this.projectList.filter((value: any) =>
        value.project_name.toLowerCase().includes(this.projectSearch.toLowerCase())
      );
    } else {
      this.filteredProjects = [...this.projectList];
    }
  } 

    filterTasks(): any {
    if (this.taskSearch) {
      this.filteredTask = this.taskList.filter((value: any) =>
        value.taskname.toLowerCase().includes(this.taskSearch.toLowerCase())
      );
    } else {
      this.filteredTask = [...this.taskList];
    }
  }

}


