// import { Component } from '@angular/core';
import { Component, ElementRef, TemplateRef, ViewChild } from '@angular/core';
import { AbstractControl, FormArray, FormBuilder, FormControl, FormGroup, UntypedFormGroup, ValidationErrors, Validators } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_LOCALE, MAT_DATE_FORMATS } from '@angular/material/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { TimesheetService } from '../../timesheet.service';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';
import { MatDialog } from '@angular/material/dialog';
import { debounceTime } from 'rxjs/operators';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};


@Component({
  selector: 'app-project-employee-mapping',
  templateUrl: './project-employee-mapping.component.html',
  styleUrls: ['./project-employee-mapping.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})


export class ProjectEmployeeMappingComponent {
  @ViewChild('searchInput') searchInput!: ElementRef;
  @ViewChild('editDialog', { static: false })
  editDialogTemplate!: TemplateRef<any>;


  allTeamMappings: any[] = [];
  filteredTeamMappings: any[] = [];
  pipe = new DatePipe('en-US');
  searchControl = new FormControl('');
  editIndex: number | null = null;
  viewMode = false;
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
 pageSizeOptions: number[] = [5, 10, 20];
  pageLoading = true;
  dataSource: MatTableDataSource<any> = <any>[];
  editing = true;
  editProjectId: any;
  isAdd = false;
  isEditMode = false;
  displayedColumns: string[] = [
    'sno',
    'project',
    'empname',
    'is_billable',
    'worktype',
    'hours',
    'status'
  ];

  teamData: any[] = [];
  employeesData: any = [];
  projectList: any = [];
  statusList = [
    { id: 1, name: 'Active' },
    { id: 0, name: 'Inactive' }
  ];
  workTypes = [
    { id: 1, name: 'Full-Time' },
    { id: 2, name: 'Part-Time' }
  ];

  billableOptions = [
    { id: 1, name: 'Yes' },
    { id: 2, name: 'No' }
  ];


  searchTerm = '';
  userSession: any;
  editedTaskId = null;
  projectMasterForm: any = UntypedFormGroup;
  editForm: any = UntypedFormGroup;
  dialogRef: any;
  constructor(private fb: FormBuilder, private route: Router,
    private datePipe: DatePipe,
    private timesheetService: TimesheetService,
    private snackbarService: CommonSnackbarService,
    private dialog: MatDialog
  ) { }

  projectSearchControl = new FormControl('');
  projectSearchControl2 = new FormControl('');
  filteredProjects: any = [];
  filteredProjects2: any = [];

  employeeSearch: string[] = [];
  filteredEmployees: any[][] = [];
  roleList: any = [];
  selectedEmpId: any;
  selectedEmpProject: any;
  projectStartDate: any;
  projectEndtDate: any;
  selectedEmpName: any;
  employeeSearchControls: FormControl[] = [];
  ngOnInit() {
    this.getAllProjects();
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.projectMasterForm = this.fb.group({
      project: ['', Validators.required],
      startDate: [''],
      endDate: [''],
      teamMembers: this.fb.array([])
    });

    this.editForm = this.fb.group({
      project: [''],
      startDate: [''],
      endDate: [''],
      employee: ['',Validators.required],
      role: ['', Validators.required],
      isBillable: ['', Validators.required],
      workType: ['', Validators.required],
      hours: ['', [Validators.required,Validators.min(1) ,Validators.max(24)]],
      status: ['', Validators.required],
    });

    this.addNewEntry();
    this.getRoleList();
    this.projectSearchControl.valueChanges.subscribe(searchText => {
      this.filterProjects(searchText);
    });
        this.projectSearchControl2.valueChanges.subscribe(searchText => {
      this.filterProjects2(searchText);
    });
    this.getAssignedEmployeeList(0);
    this.editForm.get('project')?.valueChanges.subscribe((selectedValue: any) => {
      const selectedProject = this.projectList.find((p: any) => p.id === selectedValue);
      if (selectedProject) {
        this.editForm.patchValue({
          startDate: this.datePipe.transform(selectedProject.start_date, 'yyyy-MM-dd'),
          endDate: this.datePipe.transform(selectedProject.end_date, 'yyyy-MM-dd')
        });
      }
      
    })
  }

  filterProjects(searchText: any) {
    this.filteredProjects = this.projectList.filter((val: any) =>
      val.project_name.toLowerCase().includes(searchText.toLowerCase())
    );
  }
  filterProjects2(searchText: any) {
    this.filteredProjects2 = this.projectList.filter((val: any) =>
      val.project_name.toLowerCase().includes(searchText.toLowerCase())
    );
  }
  onProjectChange(projectId: number) {
    const selectedProject = this.projectList.find((p: any) => p.id === projectId);
    if (selectedProject) {
      this.projectMasterForm.patchValue({
        startDate: this.datePipe.transform(selectedProject.start_date, 'dd-MM-yyyy'),
        endDate: this.datePipe.transform(selectedProject.end_date, 'dd-MM-yyyy')
      });
    }
    this.getEmployeeList(projectId);
  }

  getRoleList() {
    this.timesheetService.getProjectRoles().subscribe((res: any) => {
      if (res.status) {
        this.roleList = res.data;
      }
    })
  }

  get entries(): FormArray {
    return this.projectMasterForm?.get('teamMembers') as FormArray;
  }


  createEntry(): FormGroup {
    const entry = this.fb.group({
      empname: ['', [Validators.required, this.duplicateEmployeeValidator.bind(this)]],
      role: ['', Validators.required],
      isBillable: ['', Validators.required],
      workType: ['', Validators.required],
      hours: ['', [Validators.required,Validators.min(1) ,Validators.max(24)]],
    });

    // Create a separate search control for each entry
    const searchControl = new FormControl('');
    this.employeeSearchControls.push(searchControl);

    // Setup filtering logic for this control
    const index = this.employeeSearchControls.length - 1;
    searchControl.valueChanges.pipe(debounceTime(300)).subscribe((searchText) => {
      this.filterEmployees(searchText, index);
    });

    // Initialize filtered list for this entry
    this.filteredEmployees.push([...this.employeesData]);

    return entry;
  }

  duplicateEmployeeValidator(control: AbstractControl): ValidationErrors | null {
  const selectedEmpId = control.value;
  const duplicate = this.entries.controls.filter((entry) => entry.get('empname')?.value === selectedEmpId).length > 1;
  
  return duplicate ? { duplicateEmployee: true } : null;
}

  addNewEntry() {
    if (this.entries.length > 0) {
      const lastEntry = this.entries.at(this.entries.length - 1) as FormGroup;
      lastEntry.markAllAsTouched();

      if (lastEntry.invalid) {
        return;
      }
    }
    this.entries.push(this.createEntry());
  }

   filterEmployees(searchText: any, index: number) {
    // this.filteredEmployees[index] = this.employeesData.filter((emp:any) =>
    //   emp.empname.toLowerCase().includes(searchText.toLowerCase())
    // );
    const selectedIds = this.getSelectedEmployeeIds();

  const currentEmpId = this.entries.at(index).get('empname')?.value;



  this.filteredEmployees[index] = this.employeesData.filter((emp: any) => {

    const matchesSearch =

      emp.empname.toLowerCase().includes((searchText || '').toLowerCase());



    const isAlreadySelected =

      selectedIds.includes(emp.empid) && emp.empid !== currentEmpId;



    return matchesSearch && !isAlreadySelected;

  });
  }

  openAutocomplete(index: number) {
    // Reset the filtered list when the input is focused
    this.filteredEmployees[index] = [...this.employeesData];
  }

  selectEmployee(empid: string, index: number) {

  const empControl = this.entries.at(index).get('empname');
  empControl?.setValue(empid);
  empControl?.updateValueAndValidity(); 

  const selectedEmployee = this.employeesData.find((emp:any) => emp.empid === empid);
  this.employeeSearchControls[index].setValue(selectedEmployee ? selectedEmployee.empname : '');
  this.entries.controls.forEach((_, i) => {

    this.filterEmployees(this.employeeSearchControls[i].value, i);

  });
}

getEmployeeName(empid: string | null): string {
  const emp = this.employeesData.find((e:any) => e.empid === empid);
  return emp ? emp.empname : '';
}

removeEntry(index: number) {
  if (this.entries.length === 1) {
    // Clear the last entry instead of removing it if it's the only row
    this.entries.at(index).reset();
    this.employeeSearchControls[index].setValue('');
    this.filteredEmployees[index] = [...this.employeesData];
  } else {
    // Remove the row if it's not the only row
    this.entries.removeAt(index);
    this.employeeSearchControls.splice(index, 1);
    this.filteredEmployees.splice(index, 1);
  }
}

  submitForm() {
    this.projectMasterForm.markAllAsTouched();

    const rawEntries = this.projectMasterForm.value.teamMembers;

    const validEntries = rawEntries.filter((entry: any) => {
      return entry.empname || entry.role || entry.isBillable || entry.workType || entry.hours;
    });
    // If no filled entries, block submit
    if (validEntries.length === 0) {
      this.snackbarService.show('Please fill at least one entry before submitting.', false);
      return;
    }

    // Validate each filled entry manually
    for (let i = 0; i < validEntries.length; i++) {
      const entryGroup = this.entries.at(i) as FormGroup;

      if (entryGroup.invalid) {
        entryGroup.markAllAsTouched();
        this.snackbarService.show('Please complete all required fields correctly.', false);
        return;
      }
    }
    const inputData = validEntries.map((entry: any) => ({
      empid: entry.empname,
      projectid: this.projectMasterForm.value.project,
      isbillable: entry.isBillable,
      worktype: entry.workType,
      roleid: entry.role,
      hours: entry.hours,
      status: 1,

    }));

    let payload = {
      mapping_data: inputData
    }
  
    this.timesheetService.setTimesheetEmployeeProjectMapping(payload).subscribe((res: any) => {
      if (res.status) {
        let value = res.data[0]
        if (value.successstate == 0) {
          this.snackbarService.show('Data saved successfully.', true);
          this.route.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.route.navigate(["timesheet/project-team"]));

        } else {
          this.snackbarService.show('Unable to save data.', false);
        }

      } else {
        this.snackbarService.show('Unable to save data.', false);
      }
    })

  }


  ngAfterViewInit(): void {
    // This is where you can safely access editDialogTemplate
    if (!this.editDialogTemplate) {
      console.error('TemplateRef is undefined');
    }
  }

  openEditDialog(element: any): void {
    if (!this.editDialogTemplate) {
      console.error('TemplateRef is undefined');
      return;
    }

    const dialogRef = this.dialog.open(this.editDialogTemplate, {
      data: element,
    });
    this.dialogRef = dialogRef;  // Store the dialogRef here
    let employeeId = element.empid;
    this.editForm.controls.employee.setValue(employeeId);
    this.selectedEmpName = element.empname;
    this.selectedEmpProject = element.project_name;
    this.projectStartDate = element.start_date;
    this.projectEndtDate = element.end_date;

    dialogRef.afterOpened().subscribe(() => {
      this.editForm.patchValue({
        project: element.project_id,
        role: element.project_role_id,
        isBillable: element.is_billable,
        workType: element.worktype,
        hours: element.worktype_hours,
        status: element.mapping_status,
      });
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result) {
      }
    });
  }

  updateForm() {

    if (this.editForm.valid) {

      const formData = this.editForm.value;
      let inputData = [{
        empid: formData.employee,
        projectid: formData.project,
        isbillable: formData.isBillable,
        worktype: formData.workType,
        roleid: formData.role,
        hours: formData.hours,
        status: formData.status,
      }]

      let payload = {
        mapping_data: inputData
      }

      this.timesheetService.setTimesheetEmployeeProjectMapping(payload).subscribe((res: any) => {
        if (res.status) {
          let value = res.data[0]
          if (value.successstate == 0) {
            this.snackbarService.show('Data updated successfully.', true);
            this.route.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.route.navigate(["timesheet/project-team"]));
            if (this.dialogRef) {
              this.dialogRef.close();
            }
          } else {
            this.snackbarService.show('Unable to update data.', false);
          }

        } else {
          this.snackbarService.show('Unable to update data.', false);
        }
      })
    }
  }

  closeDialog(): void {
    this.dialog.closeAll();
  }
  /*************************** */



  getEmployeeList(projectId:any) {

    this.timesheetService.getEmployeesForProjectAssignment(projectId).subscribe((res: any) => {
      if (res.status) {
        this.employeesData = res.data;
           this.filteredEmployees = this.entries.controls.map(() => [...this.employeesData]);
      }
    })
  }

  getAllProjects() {
    this.timesheetService.getAllActiveProjects().subscribe((res: any) => {
      if (res.status) {
        this.projectList = res.data;
        this.filteredProjects = res.data;
        this.filteredProjects2 = res.data;
      }
    });
  }

  filterByProject(projectId: number | null) {

    if (!projectId) {
      this.filteredTeamMappings = [...this.allTeamMappings];
    } else {
      this.filteredTeamMappings = this.allTeamMappings.filter(
        (item) => item.project_id === projectId
      );
    }
    this.dataSource = new MatTableDataSource(this.filteredTeamMappings)
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
    this.pageLoading = false;
  }


  add() {
    this.isAdd = true;
    this.isEditMode = false;
  }

  cancel() {
    this.isAdd = false;
    this.isEditMode = false;
    this.viewMode = false;
    this.projectMasterForm.reset();
    this.route.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.route.navigate(["timesheet/project-team"])
    );
  }


  getProjectName(project_id: number): any {
    const project = this.projectList.find((p: any) => p.id === project_id);
    return project ? project.project_name : '';
  }

  getWorkTypeName(id: number): string {
    const type = this.workTypes.find(w => w.id === id);
    return type ? type.name : '';
  }

  getBillableName(id: number): string {
    const billable = this.billableOptions.find(b => b.id === id);
    return billable ? billable.name : '';
  }


  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }

  getAssignedEmployeeList(id: any) {
    this.timesheetService.getEmployeesProjectAssignmentHistory(id).subscribe((res: any) => {
      if (res.status && res.data.length > 0) {

        this.teamData = res.data;
        this.filteredTeamMappings = [...this.teamData];
        this.allTeamMappings = [...this.teamData];
        this.dataSource = new MatTableDataSource(this.teamData)
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
        this.getPageSizes();
      }
    })
  }


  onToggleChange(data: any) {

    let status = data.mapping_status ? 1 : 0;
    let inputData = [{
      projectid: data.project_id,
      empid: data.empid,
      isbillable: Number(data.is_billable),
      worktype: Number(data.worktype),
      status: Number(status),
      roleid: data.project_role_id,
      hours: data.worktype_hours,
    }];

    let payload = {
      mapping_data: inputData
    }

    this.timesheetService.setTimesheetEmployeeProjectMapping(payload).subscribe((res: any) => {
      let value = res.data[0];
      if (res.status && value.successstate == 0) {
        let message = data.mapping_status ? 'Employee status has been successfully activated.' : 'Employee status has been successfully inactivated.'
        this.snackbarService.show(message, true);
        this.getAssignedEmployeeList(0);
      } else {
        this.snackbarService.show('Unable to update data', false);
        this.getAssignedEmployeeList(0);
      }
    })
  }

 getPageSizes() {
  const customPageSizeArray: number[] = [];
  const dataLength = this.dataSource?.data?.length || 0;
  
  if (dataLength > 5) {
    customPageSizeArray.push(5);
  }
  if (dataLength > 10) {
    customPageSizeArray.push(10);
  }
  if (dataLength > 30) {
    customPageSizeArray.push(30);
  }

  if (dataLength > 0) {
    customPageSizeArray.push(dataLength);
  }

  this.pageSizeOptions = customPageSizeArray;
}

getSelectedEmployeeIds(): string[] {

  return this.entries.controls

    .map(ctrl => ctrl.get('empname')?.value)

    .filter(val => !!val);

}


}
