import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { NumberInput } from '@angular/cdk/coercion';
import { TimesheetService } from '../../timesheet.service';
import { DatePipe } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';
const moment =  _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-client-master',
  templateUrl: './client-master.component.html',
  styleUrls: ['./client-master.component.scss'],
     providers: [
      {provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE]},
  
      {provide: MAT_DATE_FORMATS, useValue: MY_FORMATS},
    ],
})
export class ClientMasterComponent implements OnInit {

  pageSize: NumberInput;
  clientForm: any = UntypedFormGroup;
  userSession: any ;
  todayDate: any = new Date();
  displayedColumns: string[] = ['sno', 'client', 'contactName', 'designation','contactNumber', 'startDate',  'status', 'action'];
  companyClientsData: any = [];
  dataSource: MatTableDataSource<any> = <any>[];
  pageLoading = true;

  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
 pageSizeOptions: number[] = [5, 10, 20];

  companyDBName: any;
  isSave: boolean | undefined;
  isdata: boolean = false;
  countries: any = [];
  states: any = [];
  cities: any = [];
  btnDisable: any;
  isUpdate: any;
  LMS: any;
  CountryDetails: any;
  companyForm: any;
  isdisabled: any;
  stateDetails: any;
  cityDetails: any;
  addMode: any;
  pipe: any;
  spinner: any;
  client: any;
  adminService: any;
  subscriptionflag: any;
  clientid: null | undefined;
  enable: any;
  newdata: boolean = true
  isAddMode = true;
  isEditMode = false;
  maxFromDate:any = new Date();
  constructor(
    private formBuilder: UntypedFormBuilder,
    private router: Router,
    private companyService: CompanySettingService,
    private TimesheetService: TimesheetService,
    private snackbarService:CommonSnackbarService,
    private datePipe: DatePipe ) { }
    
  ngOnInit() {
    this.getCountry();
    this.getCompanyClients();
     this.pipe = this.datePipe;

  this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
   this.clientForm = this.formBuilder.group({
    client: ['', [Validators.required]],
    contactName: ['', [Validators.required, Validators.pattern(/^[a-zA-Z\s]*$/)]],
    designation: ['', [Validators.required]],
    contactNumber: ['', [Validators.required,Validators.minLength(6),
    Validators.maxLength(16), Validators.pattern("^[0-9]{10,16}$") ]],
    email:["",[Validators.email, Validators.pattern('^[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,4}$')]],
    startDate: ['', [Validators.required]],
    address: ['', [Validators.required, Validators.minLength(6) ]],
    country: ['', [Validators.required]],
    state: ['', [Validators.required]],
    city: ['', [Validators.required]],
    pincode: ['', [Validators.required]],
    status: ['Active']
  })

  this.clientForm.get('country')?.valueChanges.subscribe((selectedValue: any) => {
    this.stateDetails = [];
    this.companyService.getStatesc(selectedValue).subscribe((data: { data: never[]; }) => {
      this.stateDetails = data.data;
      if (this.clientForm != null) {
        this.clientForm.controls.state.setValue(this.clientForm.stateid);
      }
    })
  })
  this.clientForm.get('state')?.valueChanges.subscribe((selectedValue: any) => {
    this.clientForm.controls.city.setValue("");
    this.cityDetails = [];
    this.companyService.getCities(selectedValue).subscribe((data: { data: never[]; }) => {
      this.cityDetails = data.data
      if (this.clientForm != null && selectedValue == this.clientForm.stateid) {
        this.clientForm.controls.city.setValue(this.clientForm.locationid);
      }
    })
  })
}
getCountry() {
  this.companyService.getCountry('countrymaster', null, 1, 10, this.companyDBName).subscribe((results: { data: any; }) => {
    this.CountryDetails = results.data;
  })
}

getCompanyClients() {

  this.TimesheetService.getAllTimesheetClients().subscribe((info: any) => {
    if (info.status && info.data.length !== 0) {
      this.companyClientsData = info.data;
      this.dataSource = new MatTableDataSource(this.companyClientsData);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
      this.pageLoading = true;
      this.getPageSizes();
    } else {
      this.companyClientsData = [];
      this.dataSource = new MatTableDataSource(this.companyClientsData);
    }
  })
}

submit() {
  this.saveTimesheetData();
}

saveTimesheetData() {
  if(this.clientForm.valid) {
    if (this.btnDisable) {
      return;
    }
    const data = {
      id: this.clientid !=null ? this.clientid:null,
      client_name: this.clientForm.controls.client.value.trim(),
      client_contact_name: this.clientForm.controls.contactName.value.trim(),
      client_contact_designation: this.clientForm.controls.designation.value,
      client_contact_number: this.clientForm.controls.contactNumber.value,
      client_contact_email: this.clientForm.controls.email?.value || '',
      client_start_date: this.pipe.transform(this.clientForm.controls.startDate.value, 'yyyy-MM-dd'),
      client_address: this.clientForm.controls.address.value || '',
      country: this.clientForm.controls.country.value,
      state: this.clientForm.controls.state.value,
      city: this.clientForm.controls.city.value,
      zipcode: this.clientForm.controls.pincode.value,
      status: this.clientid !=null ? this.clientForm.controls.status.value:'Active',
      created_by: this.userSession.id
      
    };
    this.btnDisable = true;
    this.TimesheetService.setTimesheetClient(data).subscribe((res: any) => {
      if (res.status) {
        let value =res.data[0]
        if (value.statuscode == 0) {
          this.snackbarService.show('Client details saved successfully.', true);
          this.cancel();
        } else if( value.statuscode == 1){
          this.snackbarService.show('Record already exists.', false);
          this.btnDisable = false;
         } else if( value.statuscode == 2){
          this.snackbarService.show('Client details updated successfully.', true);
          this.cancel();
        } 
      
      
      } else {
        this.snackbarService.show('Unable to save data.', false);
        this.btnDisable = false;
         this.cancel();
      }
    });
  }
}

add() {
  this.clientForm.reset(); 
  this.clientForm.enable(); 
  this.isdata = true;      
  this.isUpdate = false;    
  this.addMode = true;
}

cancel() {
  this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
  this.router.navigate(['/timesheet/client-master']));
}

edit(event: any, row: any) {
  this.isUpdate = true;
  this.isEditMode = true;
  this.isdata = true;
  this.clientid= row.id;
  const statusValue = row.status === null ? 'Active' : row.status;
  this.clientForm.patchValue({
    client: row.client_name,
    contactName: row.client_contact_name,
    designation: row.client_contact_designation,
    contactNumber: row.client_contact_number,
    email:row.client_contact_email,
    startDate: row.client_start_date,
    address: row.client_address,
    country: row.country, 
    // state: row.state, 
    // city: row.city, 
    pincode: row.zipcode,
    status: statusValue

  });
  // this.clientForm.enable(); 
  this.clientForm.get('status')?.enable();
  this.companyService.getStatesc(row.country).subscribe((stateRes: any) => {
    this.stateDetails = stateRes.data;
    this.clientForm.controls['state'].setValue(row.state);

    // Then fetch and set the cities
    this.companyService.getCities(row.state).subscribe((cityRes: any) => {
      this.cityDetails = cityRes.data;
      this.clientForm.controls['city'].setValue(row.city);
    });
  });
  this.clientForm.get('status')?.enable();
}


  view(row: any) {
    this.isdata = true;
    this.clientid = row.id;
    this.clientForm.disable();  // View mode, disable form
  
    const statusValue = row.status === null ? 'Active' : row.status;
  
    // Set independent fields first
    this.clientForm.patchValue({
      client: row.client_name,
      contactName: row.client_contact_name,
      designation: row.client_contact_designation,
      contactNumber: row.client_contact_number,
      email:row.client_contact_email,
      startDate: row.client_start_date,
      address: row.client_address,
      country: row.country,
      pincode: row.zipcode,
       status: statusValue
    });
  
    // // Fetch states, then set state
    this.companyService.getStatesc(row.country).subscribe((stateRes: any) => {
      this.stateDetails = stateRes.data;
      this.clientForm.controls['state'].setValue(row.state);
  
    //   // Fetch cities, then set city
      this.companyService.getCities(row.state).subscribe((cityRes: any) => {
        this.cityDetails = cityRes.data;
        this.clientForm.controls['city'].setValue(row.city);
      });
     });
  }
  
  
  
  
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

    getPageSizes() {
  const customPageSizeArray: number[] = [];
  const dataLength = this.dataSource?.data?.length || 0;
  
  if (dataLength > 5) {
    customPageSizeArray.push(5);
  }
  if (dataLength > 10) {
    customPageSizeArray.push(10);
  }
  if (dataLength > 30) {
    customPageSizeArray.push(30);
  }

  if (dataLength > 0) {
    customPageSizeArray.push(dataLength);
  }

  this.pageSizeOptions = customPageSizeArray;
}

}
