import { Component, OnInit, Inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';

@Component({
  selector: 'app-pending-tasks-dialog',
  templateUrl: './pending-tasks-dialog.component.html',
  styleUrls: ['./pending-tasks-dialog.component.scss']
})
export class PendingTasksDialogComponent implements OnInit {

  constructor(
    public dialogRef: MatDialogRef<PendingTasksDialogComponent>,
    private snackBar: MatSnackBar,
    @Inject(MAT_DIALOG_DATA) public data: { tasks: any[] }
  ) { }

  ngOnInit(): void {
    // Optional: Show snackbar immediately on dialog open
    // this.showTopSnackbar('Project has pending tasks', false);
  }

  closeDialog() {
    this.dialogRef.close();
  }

  showTopSnackbar(message: string, isSuccess: boolean = true) {
    this.snackBar.open(message, 'Ok', {
      duration: 5000,  // 5 seconds
      horizontalPosition: 'center',
      verticalPosition: 'top',
      panelClass: isSuccess ? ['snackbar-success'] : ['snackbar-error']
    });
  }
}
