import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { DatePipe } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { TimesheetService } from '../../timesheet.service';
import { FormBuilder, FormGroup } from '@angular/forms';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';
import { NgxSpinnerService } from 'ngx-spinner';
import { MatDialog } from '@angular/material/dialog';
import { PendingTasksDialogComponent } from '../../dialog-box/pending-tasks-dialog/pending-tasks-dialog.component';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-project-master',
  templateUrl: './project-master.component.html',
  styleUrls: ['./project-master.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ProjectMasterComponent implements OnInit {



  projectMasterForm!: FormGroup;

  filteredvalues: any = [];//getTimesheetprojects
  userSession: any;
  pipe = new DatePipe('en-US');
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = false;
  isSave: boolean = false;
  viewMode: boolean = false;
  enable: any = null;
  valid: boolean = false;
  start_date = new Date();
  end_date: any;
  msgEM1: any;
  btnDisable: boolean = false;
  fullTimeProjectManagers: any = [];

  todayDate: any = new Date();


  displayedColumns: string[] = [
    'sno',
    'clientid',
    'name',
    'start_date',
    'end_date',
    'estimated_efforts',
    'status',
    'actions',
  ];



  dataSource: MatTableDataSource<any> = <any>[];

  pageLoading = true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  @ViewChild('tableSection') tableSection!: ElementRef;
  @ViewChild('searchInput') searchInput!: ElementRef;
  pageSizeOptions: number[] = [5, 10, 20];

  messagesDataList: any = [];
  companyDBName: any;
  projectList: any[] = [];
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  fb: any;
  msgEM42: any;
  msgEM43: any;
  selectedProjectId: any;
  editProjectId: any;
  cdr: any;
  msgEM41: any;
  filteredManagers: any;
  managerSearch: any;
  selectedManager: any;
  searchControl = new FormControl('');
  constructor(private formBuilder: FormBuilder, private spinner: NgxSpinnerService, private dialog: MatDialog,
    private router: Router,
    private timesheetService: TimesheetService,
    private snackbarService: CommonSnackbarService,) {
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }
  clientList: any = [];//gettimesheetclients
  managersData: any[] = []; //getManagersList
  statusList: string[] = [
    'Active',
    'Completed',
    'On Hold',
  ];
  workTypes = [
    { id: 1, name: 'Full-Time' },
    { id: 2, name: 'Part-Time' }
  ];

  billableOptions = [
    { id: 1, name: 'Yes' },
    { id: 2, name: 'No' }
  ];
  isFullTImeManagersAvoided: any = true;

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyDBName = sessionStorage.getItem("companyName")
    this.searchControl = new FormControl('');
    this.getTimesheetProjects();
     this.getManagersList();

    this.getAllActiveTimesheetClients();
    this.projectMasterForm = this.formBuilder.group(
      {
        clientid: ['', Validators.required],
        name: ['', [Validators.required]],
        teamsize: ['', Validators.required],
        start_date: ['', Validators.required],
        end_date: ['', Validators.required],
        estimated_efforts: ['', Validators.required],
        budget: ['', Validators.required],
        status: ['', Validators.required],
        description: ['', Validators.required],
        manager_id: ['', Validators.required],
        worktype: ['', Validators.required],
        is_billable: ['', Validators.required],
        hours: ['', [Validators.required, Validators.min(1), Validators.max(24), Validators.pattern(/^\d+(\.\d{1,2})?$/)]],
      },
    );
    this.searchControl.valueChanges.subscribe((value) => {
      this.managerSearch = value;
      this.filterManagers()

    });

    this.projectMasterForm.get('start_date')?.valueChanges.subscribe((selectedValue: any) => {
      this.minToDate = selectedValue._d;
    })
    this.projectMasterForm.get('end_date')?.valueChanges.subscribe((selectedValue: any) => {
      this.maxFromDate = selectedValue._d;
    })
  }

  getTimesheetProjects() {
    this.spinner.show();
    this.timesheetService.getAllTimesheetProjects().subscribe((res: any) => {
      this.spinner.hide();
      if (res.status) {
        this.filteredvalues = res.data;
        this.fullTimeProjectManagers = this.filteredvalues.filter((val: any) => val.worktype == 1).map(((mgr: any) => mgr.manager_id));
        this.dataSource = new MatTableDataSource(this.filteredvalues);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getManagersList();
        this.getPageSizes();
      } else {
        this.filteredvalues = [];
      }
    });
  }


  getAllActiveTimesheetClients() {
    this.spinner.show();
    this.timesheetService.getAllActiveTimesheetClients('Active').subscribe((res: any) => {
      this.spinner.hide();
      if (res.status) {
        this.clientList = res.data;
      } else {
        this.clientList = [];
      }
    });
  }
  getManagersList() {
    this.spinner.show();
    this.timesheetService.getManagersList().subscribe((res: any) => {
      this.spinner.hide();
      if (res.status && res.data.length > 0) {
        this.managersData = res.data;
        this.filteredManagers = this.managersData.filter((mgr: any) => !this.fullTimeProjectManagers.includes(mgr.empId));
        // this.avoidManagersWithFullTimeProject();

      } else {
        this.managersData = [];
        this.filteredManagers = [];

      }
    });
  }

  avoidManagersWithFullTimeProject(edit_row: any = null) {
    this.filteredManagers = [...this.managersData];
    if (this.isFullTImeManagersAvoided) {
      let removeMgr = new Set(this.filteredvalues.filter((val: any) => val.worktype == 1).map(((mgr: any) => mgr.manager_id)));
      (edit_row && edit_row.manager_id) ? removeMgr.delete(edit_row.manager_id) : null;
      this.filteredManagers = this.filteredManagers.filter((fm: any) => !removeMgr.has(fm.empId));
    }
  }

  filterManagers(): any {
    if (this.managerSearch) {
      this.filteredManagers = this.filteredManagers.filter((manager: any) =>
        manager.managerName.toLowerCase().includes(this.managerSearch.toLowerCase())
      );
    } else {
      this.avoidManagersWithFullTimeProject();
    }
  }

  saveData() {
    this.submit();
  }

  submit() {
    if (this.projectMasterForm.valid) {
      if (this.btnDisable) {
        return;
      }
      const data = {
        id_value: this.isEdit ? this.editProjectId : null,
        clientid_value: this.projectMasterForm.get('clientid')?.value,
        name_value: this.projectMasterForm.get('name')?.value,
        teamsize_value: this.projectMasterForm.get('teamsize')?.value,
        start_date_value: this.pipe.transform(this.projectMasterForm.get('start_date')?.value, 'yyyy-MM-dd'),
        end_date_value: this.pipe.transform(this.projectMasterForm.get('end_date')?.value, 'yyyy-MM-dd'),
        estimated_efforts_value: this.projectMasterForm.get('estimated_efforts')?.value,
        budget_value: this.projectMasterForm.get('budget')?.value,
        status_value: this.projectMasterForm.get('status')?.value,
        description_value: this.projectMasterForm.get('description')?.value,
        manager_id_value: this.projectMasterForm.get('manager_id')?.value,
        worktype_value: this.projectMasterForm.get('worktype')?.value,
        is_billable_value: this.projectMasterForm.get('is_billable')?.value.toString(),
        hours_value: this.projectMasterForm.get('hours')?.value, 
        created_by_value: this.isEdit ? null : this.userSession.id,
        updated_by_value: this.isEdit ? this.userSession.id : null,
      };
      this.btnDisable = true;
      this.timesheetService.setTimesheetProjects(data).subscribe((res: any) => {
        if (res.status) {
          let value = res.data[0]
          if (value.statuscode == 3) {
  const tasks = JSON.parse(value.pending_tasks);

  this.dialog.open(PendingTasksDialogComponent, {
    width: '400px',
    data: { tasks }
  });

  return; // stop further execution
}
          if (value.successstate == 0) {
            this.snackbarService.show('Data saved successfully.', true);

          } else if (value.statuscode == 1) {
            this.snackbarService.show('Record already exists.', false);

          } else if (value.statuscode == 2) {
            this.snackbarService.show('Data updated successfully.', true);
          }
          this.cancel();

        }
        else {
          this.snackbarService.show('Unable to save data.', false);
        }
      });
      this.btnDisable = false;

    } else {
      this.projectMasterForm.markAllAsTouched();
    }
  }

  Add() {
    this.isAdd = true;
    this.isdata = false;
  }


  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/timesheet/project-master"]));

  }

  editRow(value: any) {
    this.isEdit = true;
    this.isAdd = true;
    this.isdata = false;
    this.viewMode = false;

    const row = value;

    this.selectedProjectId = row.id;
    this.editProjectId = row.id;

    this.projectMasterForm.patchValue({
      clientid: row.clientid,
      name: row.name,
      teamsize: row.teamsize,
      start_date: new Date(row.start_date),
      end_date: new Date(row.end_date),
      estimated_efforts: row.estimated_efforts,
      budget: row.budget,
      status: row.status,
      description: row.description,
      manager_id: row.manager_id,
      worktype: row.worktype,
      is_billable: row.is_billable,
      hours: row.hours,


    });
    this.avoidManagersWithFullTimeProject(row);
    this.projectMasterForm.enable();
  }


  viewRow(row: any) {
    this.viewMode = true;
    this.isEdit = false;
    this.isAdd = true;

    this.filteredManagers = [...this.managersData];
    this.projectMasterForm.patchValue({
      clientid: row.clientid,
      name: row.name,
      teamsize: row.teamsize,
      start_date: row.start_date,
      end_date: row.end_date,
      estimated_efforts: row.estimated_efforts,
      budget: row.budget,
      status: row.status,
      description: row.description,
      manager_id: row.manager_id,
      worktype: Number(row.worktype),
      is_billable: Number(row.is_billable),
      hours: row.hours,

    });

    this.projectMasterForm.get('clientid')?.disable();
    this.projectMasterForm.get('name')?.disable();
    this.projectMasterForm.get('teamsize')?.disable();
    this.projectMasterForm.get('start_date')?.disable();
    this.projectMasterForm.get('end_date')?.disable();
    this.projectMasterForm.get('estimated_efforts')?.disable();
    this.projectMasterForm.get('budget')?.disable();
    this.projectMasterForm.get('status')?.disable();
    this.projectMasterForm.get('description')?.disable();
    this.projectMasterForm.get('manager_id')?.disable();
    this.projectMasterForm.get('worktype')?.disable();
    this.projectMasterForm.get('is_billable')?.disable();
    this.projectMasterForm.get('hours')?.disable();
  }

  getWorkTypeName(id: number): string {
    const type = this.workTypes.find(w => w.id === id);
    return type ? type.name : '';
  }

  getBillableName(id: number): string {
    const billable = this.billableOptions.find(b => b.id === id);
    return billable ? billable.name : '';
  }

  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }

  /**Search functionality */
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  checkCheckBoxvalue(event: any) {
    this.isFullTImeManagersAvoided = event.checked;
    this.avoidManagersWithFullTimeProject();
  }
}
