import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, UntypedFormGroup } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DatePipe } from '@angular/common';
import { TimesheetService } from '../../timesheet.service';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
import { MatDialog } from '@angular/material/dialog';
import { ProjectDetailsDialogComponent } from '../../dialog-box/project-details-dialog/project-details-dialog.component';
import * as XLSX from 'xlsx';
import { MatDatepickerInputEvent } from '@angular/material/datepicker';
import { NgxSpinnerService } from 'ngx-spinner';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-project-summary-report-manager',
  templateUrl: './project-summary-report-manager.component.html',
  styleUrls: ['./project-summary-report-manager.component.scss'],
  providers: [
    {
      provide: DateAdapter,
      useClass: MomentDateAdapter,
      deps: [MAT_DATE_LOCALE],
    },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ProjectSummaryReportManagerComponent implements OnInit {

  searchForm!: UntypedFormGroup;
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
  @ViewChild('table') table!: ElementRef;
  isCustom: Boolean = false;
  userSession: any;
  statusList: string[] = [
    'Active',
    'Completed',
    'On Hold',
    'Cancelled'
  ];

  clientList: any = [];
  projectList: any = [];
  reportData: any = [];
  pageSizeOptions: number[] = [5, 10, 20];

  pipe = new DatePipe('en-US');
  displayedColumns: string[] = [
    'sno',
    'project',
    'estimatedHours',
    'workedHours',
  //   'submitted_hours',
  //  'approved_hours', 
   'rejected_hours',
    'status',
    'actions'
  ];
  List: any[] = [];
  is_super_admin: any = false;
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  constructor(private datePipe: DatePipe, private formBuilder: FormBuilder, private spinner: NgxSpinnerService,
    private timesheetService: TimesheetService,
    private pdfService: PdfHeaderService,
    public dialog: MatDialog,
  ) {
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }

  selectedClientId: any;
  selectedProject: any = [];
  selectedClient: any = [];
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    if (this.userSession.is_super_admin == "1") {
      this.is_super_admin = true;
    }
    this.searchForm = this.formBuilder.group({
      client: [0],
      project: [0],
      fromDate: [new Date()],
      toDate: [new Date()],
      DateFormate: ['currentWeek'],
      status: ['Active'],
    });
    this.getProjectList();
    const today = new Date();
    let fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
    let toDate = new Date(today.setDate(today.getDate() - today.getDay()));
    this.searchForm.controls.fromDate.setValue(fromdate);
    this.searchForm.controls.toDate.setValue(new Date(toDate.setDate(toDate.getDate() + 6)));

    this.searchForm.get('DateFormate')?.valueChanges.subscribe((selectedValue: any) => {
      const now = new Date();

  switch (selectedValue) {
    case 'currentWeek': {
      const now = new Date();
      const startOfWeek = new Date(now.getFullYear(), now.getMonth(), now.getDate() - now.getDay());
      // startOfWeek.setDate(now.getDate() - now.getDay());
      const endOfWeek = new Date();
      // endOfWeek.setDate(startOfWeek.getDate() + 6);

          this.searchForm.controls.fromDate.setValue(startOfWeek);
          this.searchForm.controls.toDate.setValue(endOfWeek);
          this.isCustom = false;
          break;
        }

        case 'lastWeek': {
          const startOfCurrentWeek = new Date(now);
          startOfCurrentWeek.setDate(now.getDate() - now.getDay());
          const startOfLastWeek = new Date(startOfCurrentWeek);
          startOfLastWeek.setDate(startOfCurrentWeek.getDate() - 7);
          const endOfLastWeek = new Date(startOfLastWeek);
          endOfLastWeek.setDate(startOfLastWeek.getDate() + 6);

          this.searchForm.controls.fromDate.setValue(startOfLastWeek);
          this.searchForm.controls.toDate.setValue(endOfLastWeek);
          this.isCustom = false;
          break;
        }

        case 'currentMonth': {
          const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
          const endOfMonth = new Date();

          this.searchForm.controls.fromDate.setValue(startOfMonth);
          this.searchForm.controls.toDate.setValue(endOfMonth);
          this.isCustom = false;
          break;
        }

        case 'lastMonth': {
          const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

          this.searchForm.controls.fromDate.setValue(startOfLastMonth);
          this.searchForm.controls.toDate.setValue(endOfLastMonth);
          this.isCustom = false;
          break;
        }

        case 'custom': {
          const today = new Date();
          this.searchForm.controls.fromDate.setValue(today);
          this.searchForm.controls.toDate.setValue(today);
          this.isCustom = true;
          break;
        }
      }
    });




    this.searchForm.get('project')?.valueChanges.subscribe((selectedValue: any) => {
      this.selectedProject.push(selectedValue)
      console.log(this.selectedProject);
    })
    this.searchform();
    this.searchForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      this.minToDate = selectedValue._d;
    })

  }
  toDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.maxFromDate = event.value;
  }
  getProjectList() {
    let payload = {
      pmid: 0,
      rmid: this.userSession.id,
    }
    this.spinner.show();
    this.timesheetService.getTimesheetProjectsByManager(payload).subscribe((res: any) => {
      this.spinner.hide();
      if (res.status && res.data.length !== 0) {
        let data = res.data;
        this.projectList = res.data;
        // this.filteredProjects = res.data;
      }
    })
  }

  searchform() {
    const formdata = this.searchForm.value;
    let payload = {
      projectid: formdata.project,
      managerid: this.userSession.id,
      fromdate: this.pipe.transform(formdata.fromDate, 'yyyy-MM-dd'),
      todate: this.pipe.transform(formdata.toDate, 'yyyy-MM-dd'),
      status_value: formdata.status,
    }
    this.List = [];
    this.spinner.show();
    this.timesheetService.getTimesheetProjectsSummaryReportForManager(payload).subscribe((res: any) => {
      this.spinner.hide();
      if (res.status && res.data.length !== 0) {
        this.List = res.data.map((item: any) => {
        const submitted = parseFloat(item.submitted_hours) || 0;
        const approved = parseFloat(item.approved_hours) || 0;
        return {
          ...item,
          worked_hours: (submitted + approved).toFixed(2)
        };
        });
        this.dataSource = new MatTableDataSource(this.List);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      } else {
        this.dataSource = new MatTableDataSource(this.List);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      }
    });
  }


  resetform() {
    this.ngOnInit();
    this.isCustom = false;
  }



  filterByProject(projectId: number) {

  }

  filterByStatus(statusId: number) {

  }

  viewDetails(data: any) {
    console.log("givdata",data);
        let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY");
    data.superAdmin = false;
    let givenData = {
      "data": data,
      "date":fromDate +' to '+ toDate
    }
    let dialogRef = this.dialog.open(ProjectDetailsDialogComponent, {
      width: 'auto',
      maxWidth: '80vw',
      height: 'auto',
      maxHeight: '90vh',
      minWidth: '300px',
      position: { top: `100px` },
      disableClose: true,
      data: givenData

    });

  }


  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }

  getSelectedLocationNames() {
    let selectedLocationNames: string = '';
    if (this.selectedClient) {
      this.clientList?.forEach((wl: any) => {
        if (this.selectedClient.includes(wl.id)) {
          selectedLocationNames = selectedLocationNames + (selectedLocationNames == '' ? '' : ', ') + wl.client_name;
        }
      });
    }
    let name = selectedLocationNames ? selectedLocationNames : 'All'
    return name;
  }

  getselectedProjectName() {
    let selectedProjectName: string = '';
    if (this.selectedProject && this.selectedProject.length) {
      this.projectList?.forEach((wl: any) => {
        if (this.selectedProject.includes(wl.project_id)) {
          selectedProjectName = selectedProjectName + (selectedProjectName == '' ? '' : ', ') + wl.project_name;
        }
      });
    }
    let name = selectedProjectName ? selectedProjectName : 'All Projects'
    return name;
  }

  generatePDF() {
    let emp_name = (this.userSession.firstname || '') + (this.userSession.firstname.toString().length > 0 ? ' ' : '') + (this.userSession.middlename || '') + (this.userSession.middlename.toString().length > 0 ? ' ' : '') + (this.userSession.lastname || '');
    let empid = (this.userSession.empid || '');
    let branch = this.userSession.branch || "";
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY");
    let project_status = this.searchForm.controls.status.value;
    let selections = ``;
    selections = `Date: ${fromDate} to ${toDate},    Manager:${emp_name}(${empid}),    Branch:${branch}`;
    selections = selections + `\n` + `Project Status:${project_status}`;
    selections = selections + `\n` + `Projects: ${this.getselectedProjectName()}`;
    let headers = ['S.No', 'Project', 'Estimated Hours',
        'Worked Hours', 'Rejected Hours', 'Status'];
    let tblWidths: any = { 0: { cellWidth: 25 }, 1: { cellWidth: 30 },
     2: { cellWidth: 30 }, 3: { cellWidth: 30 },
     4: { cellWidth: 30 }, 5: { cellWidth: 20 }};
    let tblBody: any = [
      ...this.List.map((row, index) => [
        index + 1,
        row.project ?? '',
        row.estimated_efforts,
        row.worked_hours ?? '',
      //   row.submitted_hours ?? '',
      //  row.approved_hours ?? '',
       row.rejected_hours ?? '',
        row.status ?? '',
      ])];

    let tables = [{ headers: headers, sub_head: '', body: tblBody, widths: tblWidths, table_name: 'assignments',headers_align:'center',  columnStyles: {
    2: { halign: 'right' },  3: { halign: 'right' }, 4: { halign: 'right' }, 5: { halign: 'right' }   } }];
    this.pdfService.generatePDF_common('potrait', 'Project Summary Report', selections, tables, `project_summary_manager_report_${emp_name?.replace(/-/g,'')}_${fromDate?.replace(/-/g,'')}_${toDate?.replace(/-/g,'')}.pdf`);
  }

  exportAsXLSX() {
    let emp_name = (this.userSession.firstname || '') + (this.userSession.firstname.toString().length > 0 ? ' ' : '') + (this.userSession.middlename || '') + (this.userSession.middlename.toString().length > 0 ? ' ' : '') + (this.userSession.lastname || '');
    let fromdate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-yyyy");
    let todate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-yyyy");
    const exportData = this.List.map((row, index) => ({
      "S.No": index + 1,
      "Project": row.project,
      "Estimated Hours": row.estimated_efforts,
      "Worked Hours": row.worked_hours,
      //  "Submitted Hours":row.submitted_hours ?? '',
      //  "Approved Hours":row.approved_hours ?? '',
      "Rejected Hours":row.rejected_hours ?? '',
      "Status": row.status,
    }));

    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);

    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Project Summary Report');

    /* save to file */
    XLSX.writeFile(wb, fromdate + " - " + todate + " - " + `project_summary_manager_report_${emp_name?.replace(/-/g, '')}_${fromdate?.replace(/-/g, '')}_${todate?.replace(/-/g, '')}.xlsx`);
  }
}
