import { Component, OnInit, ViewChild, ElementRef  } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TimesheetService } from '../../timesheet.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { Router } from '@angular/router';
import { MatSort } from '@angular/material/sort';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';


@Component({
  selector: 'app-project-role-configuration',
  templateUrl: './project-role-configuration.component.html',
  styleUrls: ['./project-role-configuration.component.scss']
})
export class ProjectRoleConfigurationComponent implements OnInit {

  displayedColumns: string[] = [
    'sno',
    'role_name',
    'actions',
  ];

  roleList: any[] = [];
  selectedProjectRole: any;
  editProjectId: any;
  projectRoleForm!: FormGroup;
  pageLoading = true;
  companyDBName: any;
  dataSource: MatTableDataSource<any> = <any>[];
  isdata: boolean = true;
  isEdit: boolean = false;
  isSave: boolean = false;
  viewMode: boolean = false;
  btnDisable: boolean = false;
  userSession: any;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  @ViewChild('roleNameInput') roleNameInput!: ElementRef<HTMLInputElement>;

  formBuilder: any;

  constructor(private fb: FormBuilder, private router: Router,
    private timesheetService: TimesheetService,
    private snackbarService: CommonSnackbarService) {
  }

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.projectRoleForm = this.fb.group({
      // role_name: ['', [Validators.required]],
      role_name: ['', [Validators.required, this.duplicateRoleValidator() ]],
    });
    this.getProjectRoles();
  }


  getProjectRoles(): void {
    this.timesheetService.getProjectRoles().subscribe((res: any) => {
      if (res.status) {
        this.roleList = res.data;
        this.dataSource = new MatTableDataSource(this.roleList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
      } else {
        this.roleList = [];
      }
    });
  }
   duplicateRoleValidator() {

  return (control: any) => {

    if (!control.value) return null;

 

    const value = control.value.trim().toLowerCase();

 

    const duplicate = this.roleList.some(role =>

      role.role_name.toLowerCase() === value &&

      (!this.isEdit || role.id !== this.editProjectId) // ✅ ignore current row in edit

    );

 

    return duplicate ? { duplicate: true } : null;

  };

}

  saveData() {
    this.submit();
  }
  submit() {
    if (this.projectRoleForm.valid) {
      if (this.btnDisable) {
        return;
      }
          if (this.projectRoleForm.get('role_name')?.hasError('duplicate')) {

    this.snackbarService.show('Record already exists.', false);

    return;

  }

 

      const data = {
        id_value: this.isEdit ? this.editProjectId : null,
        role_name_value: this.projectRoleForm.get('role_name')?.value,
        created_by_value: this.isEdit ? null : this.userSession.id,
        updated_by_value: this.isEdit ? this.userSession.id : null,
      };

      this.btnDisable = true;

      this.timesheetService.setTimesheetProjectRole(data).subscribe((res: any) => {
        if (res.status) {
          let value = res.data[0];

          if (value.statuscode == 0) {
            this.snackbarService.show('Data saved successfully.', true);

          } else if (value.statuscode == 1) {
            this.snackbarService.show('Record already exists.', false);


          } else if (value.statuscode == 2) {
            this.snackbarService.show('Data updated successfully.', true);

          }

          this.cancel();

        } else {
          this.snackbarService.show('Unable to save data.', false);

        }
      });
      this.btnDisable = false;
    } else {
      this.projectRoleForm.markAllAsTouched();
    }
  }


  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/timesheet/project-roles"]));

  }

  editRow(value: any) {
    this.isEdit = true;
    this.isdata = false;
    this.viewMode = false;
    this.editProjectId = value.id;

    const element = value;

    this.selectedProjectRole = element.role_name;
    this.editProjectId = element.id;

    this.projectRoleForm.patchValue({
      // role_name: element.role_name,
      role_name: value.role_name


    });

    this.projectRoleForm.enable();
     setTimeout(() => {
    if (this.roleNameInput) {
      // Scroll to input
      this.roleNameInput.nativeElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
      
      // Focus input
      this.roleNameInput.nativeElement.focus();
    }
  }, 200);
  }
    applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  

}
