import { Component, OnInit, ViewChild } from '@angular/core';
import { DatePipe } from '@angular/common';
import { NgxSpinnerService } from 'ngx-spinner';
import { UntypedFormBuilder, UntypedFormGroup } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { ChartComponent } from 'angular2-chartjs';
import { TimesheetService } from '../../timesheet.service';
// import { LegendPosition, ScaleType } from '@swimlane/ngx-charts';
// import {default as _rollupMoment} from 'moment';
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    // dateInput: 'MM-YYYY',
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-manager-dashboard',
  templateUrl: './manager-dashboard.component.html',
  styleUrls: ['./manager-dashboard.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],

})
export class ManagerDashboardComponent implements OnInit {
  pipe = new DatePipe('en-US');
  dashBoardForm: any = UntypedFormGroup;
  companyName: any;

  @ViewChild(ChartComponent)
  chart!: ChartComponent;
  locPieChartType: any;
  locPieChartdata: any;
  locPieChartoptions: any;

  vbarChartType: any;
  vbarChartData: any;
  vbaroptions: any;

  varianceDoughChartType: any;
  varianceChartOptions: any;
  varianceDoughChartData: any;

  // --------------------------------------------
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  // --------------------------------------------

  userSession: any;
  constructor(
    private datePipe: DatePipe,
    private timesheetService: TimesheetService,
    private spinner: NgxSpinnerService,
    private formBuilder: UntypedFormBuilder,
  ) {
    this.companyName = sessionStorage.getItem('companyName');
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.dashBoardForm = this.formBuilder.group(
      {
        location: ["",],
        shiftName: ["",],
        employeeStatusMonthDate: [new Date()],
        attendanceWiseDate: [new Date()],
        deptWiseleavesDate: [new Date()],
        leaveStatusDate: [new Date()],

        // ---------------------
        fromDate: [new Date()],
        toDate: [new Date()],
        DateFormate: ['currentWeek'],
      });
    // -------------------------------
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }

  projectHours: any = [];
  totalClients: any;
  totalProjects: any;
  totalprojectAssignedEmployees: any;
  totalprojectUnassignedEmployees: any;
  donutChartData: any = [];
  projectVarianceNameLis: any = ['Projects With Variance', 'Projects Without Variance'];
  varianceCountLis: any = [];
  projectsTotalHoursCount: any = [];
  allProjectsNameList: any = [];
  pieChartData: any = [];
  chartContainerWidth = 0;
  hasVarianceData: boolean = false;
  hasPieData: boolean = false;
  ngOnInit(): void {


    // -----------------------------------------------
    this.getClientsCount();

    const today = new Date();
    let fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
    let toDate = new Date(today.setDate(today.getDate() - today.getDay()));
    this.dashBoardForm.controls.fromDate.setValue(fromdate);
    this.dashBoardForm.controls.toDate.setValue(new Date(toDate.setDate(toDate.getDate() + 6)));

    this.dashBoardForm.get('DateFormate')?.valueChanges.subscribe((selectedValue: any) => {
      const now = new Date();
      switch (selectedValue) {
        case 'currentWeek': {
          const startOfWeek = new Date(now);
          startOfWeek.setDate(now.getDate() - now.getDay());
          const endOfWeek = new Date(startOfWeek);
          endOfWeek.setDate(startOfWeek.getDate() + 6);

          this.dashBoardForm.controls.fromDate.setValue(startOfWeek);
          this.dashBoardForm.controls.toDate.setValue(endOfWeek);
          break;
        }

        case 'lastWeek': {
          const startOfCurrentWeek = new Date(now);
          startOfCurrentWeek.setDate(now.getDate() - now.getDay());
          const startOfLastWeek = new Date(startOfCurrentWeek);
          startOfLastWeek.setDate(startOfCurrentWeek.getDate() - 7);
          const endOfLastWeek = new Date(startOfLastWeek);
          endOfLastWeek.setDate(startOfLastWeek.getDate() + 6);

          this.dashBoardForm.controls.fromDate.setValue(startOfLastWeek);
          this.dashBoardForm.controls.toDate.setValue(endOfLastWeek);
          break;
        }

        case 'currentMonth': {
          const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
          const endOfMonth = new Date();

          this.dashBoardForm.controls.fromDate.setValue(startOfMonth);
          this.dashBoardForm.controls.toDate.setValue(endOfMonth);
          break;
        }

        case 'lastMonth': {
          const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

          this.dashBoardForm.controls.fromDate.setValue(startOfLastMonth);
          this.dashBoardForm.controls.toDate.setValue(endOfLastMonth);
          break;
        }
      }
      this.getProjectWiseHoursCount();
      this.getClientsCount();
    });
    this.getProjectWiseHoursCount();

  }

  // ----------------------------------------------------------------------------------------

  getClientsCount() {
    const fromDate = this.datePipe.transform(new Date, 'yyyy-MM-dd');
    const toDate = this.datePipe.transform(new Date, 'yyyy-MM-dd');
    const rmid = this.userSession.id;
    this.timesheetService.getTimesheetManagerDashboard(rmid, fromDate, toDate).subscribe((res: any) => {
      const totalsData = res.data[0][0];
      this.donutChartData = res.data[0][0];
      this.projectHours = res.data[1];
      this.totalProjects = totalsData.total_active_projects;
      this.totalprojectAssignedEmployees = totalsData.total_assigned_project_employees;
      this.totalprojectUnassignedEmployees = totalsData.total_unassigned_project_employees;
      this.getProjectVarianceData();
      this.getProjecBarChartData();
    })
  }




  generateRandomColors(count: number): string[] {
    const colors: string[] = [];
    for (let i = 0; i < count; i++) {
      const r = Math.floor(Math.random() * 255);
      const g = Math.floor(Math.random() * 255);
      const b = Math.floor(Math.random() * 255);
      colors.push(`rgba(${r}, ${g}, ${b}, 0.6)`);
    }
    return colors;
  }

  /** project wise hours pie chart */
  getProjectWiseHoursCount() {

    const fromDate = this.datePipe.transform(this.dashBoardForm.controls.fromDate.value, 'yyyy-MM-dd');
    const toDate = this.datePipe.transform(this.dashBoardForm.controls.toDate.value, 'yyyy-MM-dd');
    const rmid = this.userSession.id;
    this.allProjectsNameList = [];
    this.projectsTotalHoursCount = [];
    this.timesheetService.getTimesheetManagerDashboard(rmid, fromDate, toDate).subscribe((res: any) => {
      this.pieChartData = res.data[1];
      this.allProjectsNameList = this.pieChartData.map((p: any) => p.name);
      this.projectsTotalHoursCount = this.pieChartData.map((p: any) => +p.consumed_hours);

      this.hasPieData = this.projectsTotalHoursCount.some((hours: any) => hours > 0);

      // Generate a random color for each data entry
      const backgroundColors = this.projectsTotalHoursCount.map(() => this.getRandomColor());

      this.locPieChartType = 'pie';
      this.locPieChartdata = {
        labels: this.allProjectsNameList,
        render: 'percentage',
        datasets: [
          {
            backgroundColor: backgroundColors,
            data: this.projectsTotalHoursCount
          }
        ]
      }

      this.locPieChartoptions = {
        responsive: true,
        maintainAspectRatio: false,
        legend: {
          display: this.allProjectsNameList.length > 3 ? false : true,
          position: 'bottom',
        },

      }
    })
  }

  /** project variance donut chatrt */
  getProjectVarianceData() {
    const projectData = this.donutChartData;
    this.projectVarianceNameLis = ['Projects with Variance', 'Projects without Variance'];
    this.varianceCountLis = [
      projectData['Projects with Variance'],
      projectData['Projects without Variance']
    ];

    // Check for non-zero data
    const total = this.varianceCountLis.reduce((a: any, b: any) => a + b, 0);
    this.hasVarianceData = total > 0;

    this.varianceDoughChartType = 'doughnut';
    this.varianceDoughChartData = {
      labels: this.projectVarianceNameLis,
      datasets: [
        {
          backgroundColor: ["#fd0018", "#28a745"],
          data: this.varianceCountLis
        }
      ]
    }
    this.varianceChartOptions = {
      responsive: true,
      maintainAspectRatio: false,
      cutout: '65%',
      legend: { position: 'bottom' }

    }

  }


  getProjecBarChartData() {
    const labels = this.projectHours.map((p: any) => p.name);
    const estimated = this.projectHours.map((p: any) => p.estimated_hours);
    const consumed = this.projectHours.map((p: any) => p.actual_hours);
    this.chartContainerWidth = labels.length * 50;

    this.vbarChartType = 'bar';
    this.vbarChartData = {
      labels: labels,
      datasets: [
        {
          label: 'Estimated Hours',
          data: estimated,
          backgroundColor: 'rgba(54, 162, 235, 0.6)',
          hoverBackgroundColor: 'rgba(4, 92, 150, 0.6)'
        },
        {
          label: 'Consumed Hours',
          data: consumed,
          backgroundColor: 'rgba(255, 99, 132, 0.6)',
          hoverBackgroundColor: 'rgba(205, 8, 50, 0.6)',
        }
      ]
    }
    this.vbaroptions = {
      indexAxis: 'x',
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: {
          ticks: {
            autoSkip: false,
            maxRotation: 45,
            minRotation: 45
          }
        },
        y: {
          beginAtZero: true,
          ticks: {
            stepSize: 50
          }
        }
      },
      plugins: {
        legend: {
          display: false
        }
      }
    };

  }

  showSpinner() {
    this.spinner.show();
    setTimeout(() => {
      this.spinner.hide();
    }, 1000);
  }

  // Utility method to generate a random hex color
  getRandomColor(): string {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  }

}
