import { Component, ElementRef, OnInit, ViewChild, AfterViewInit,ChangeDetectorRef } from '@angular/core';
import { DatePipe } from '@angular/common';
import { NgxSpinnerService } from 'ngx-spinner';
import { UntypedFormBuilder, UntypedFormGroup } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { ChartComponent } from 'angular2-chartjs';
import { TimesheetService } from '../../timesheet.service';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { PendingTimesheetPopupComponent } from '../../dialog-box/pending-timesheet-popup/pending-timesheet-popup.component';


// import { LegendPosition, ScaleType } from '@swimlane/ngx-charts';
// import {default as _rollupMoment} from 'moment';
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    // dateInput: 'MM-YYYY',
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-employee-dashboard',
  templateUrl: './employee-dashboard.component.html',
  styleUrls: ['./employee-dashboard.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class EmployeeDashboardComponent implements OnInit {
  pipe = new DatePipe('en-US');
  dashBoardForm: any = UntypedFormGroup;
  companyName: any;
  displayedColumns: string[] = ['task_name', 'task_hours', 'start_date', 'end_date'];

  @ViewChild(ChartComponent)
  chart!: ChartComponent;
  vbarChartType: any;
  vbarChartData: any;
  vbaroptions: any;
 @ViewChild('chartWrapper', { static: false }) chartWrapper!: ElementRef;
  // --------------------------------------------
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  // --------------------------------------------

  userSession: any;
  constructor(
    private datePipe: DatePipe,
    private timesheetService: TimesheetService,
    private formBuilder: UntypedFormBuilder,
    private cdr: ChangeDetectorRef,private dialog: MatDialog,private router: Router
  ) {
    this.companyName = sessionStorage.getItem('companyName');
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.dashBoardForm = this.formBuilder.group(
      {
        fromDate: [new Date()],
        toDate: [new Date()],
        DateFormate: ['currentWeek'],
      });
    // -------------------------------
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }

  projectHours: any = [];
  projectNameList: any = [];
  tasktNameList: any = [];
  chartContainerWidth = 0;
  pendingCount: any;
  pendingDates: any[] = [];
  ngOnInit(): void {

    const today = new Date();
    let fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
    let toDate = new Date(today.setDate(today.getDate() - today.getDay()));
    this.dashBoardForm.controls.fromDate.setValue(fromdate);
    this.dashBoardForm.controls.toDate.setValue(new Date(toDate.setDate(toDate.getDate() + 6)));
    this.getTaskWiseReportList();
    this.getprojectAndTaskList();
    this.getPendingTimesheetCount();

    this.dashBoardForm.get('DateFormate')?.valueChanges.subscribe((selectedValue: any) => {
      const now = new Date();
      switch (selectedValue) {
        case 'currentWeek': {
          const startOfWeek = new Date(now);
          startOfWeek.setDate(now.getDate() - now.getDay());
          const endOfWeek = new Date(startOfWeek);
          endOfWeek.setDate(startOfWeek.getDate() + 6);

          this.dashBoardForm.controls.fromDate.setValue(startOfWeek);
          this.dashBoardForm.controls.toDate.setValue(endOfWeek);
          break;
        }

        case 'lastWeek': {
          const startOfCurrentWeek = new Date(now);
          startOfCurrentWeek.setDate(now.getDate() - now.getDay());
          const startOfLastWeek = new Date(startOfCurrentWeek);
          startOfLastWeek.setDate(startOfCurrentWeek.getDate() - 7);
          const endOfLastWeek = new Date(startOfLastWeek);
          endOfLastWeek.setDate(startOfLastWeek.getDate() + 6);

          this.dashBoardForm.controls.fromDate.setValue(startOfLastWeek);
          this.dashBoardForm.controls.toDate.setValue(endOfLastWeek);
          break;
        }

        case 'currentMonth': {
          const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
          const endOfMonth = new Date();

          this.dashBoardForm.controls.fromDate.setValue(startOfMonth);
          this.dashBoardForm.controls.toDate.setValue(endOfMonth);
          break;
        }

        case 'lastMonth': {
          const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

          this.dashBoardForm.controls.fromDate.setValue(startOfLastMonth);
          this.dashBoardForm.controls.toDate.setValue(endOfLastMonth);
          break;
        }
      }
      this.getTaskWiseReportList();
      this.getprojectAndTaskList();
      this.getPendingTimesheetCount();
    });

  }
  // ----------------------------------------------------------------------------------------

  getTaskWiseReportList() {
    const fromDate = this.datePipe.transform(this.dashBoardForm.controls.fromDate.value, 'yyyy-MM-dd');
    const toDate = this.datePipe.transform(this.dashBoardForm.controls.toDate.value, 'yyyy-MM-dd');
    const empid = this.userSession.id;
    this.timesheetService.getTimesheetEmployeeDashboard(empid, fromDate, toDate).subscribe((res: any) => {
      if (res.data.length > 0) {
        this.projectHours = res.data;
          this.cdr.detectChanges();

      // Then wait for chartWrapper to be available in the DOM
      setTimeout(() => {
        this.getTaskWiseBarChartData();
      });
      }
    })
  }


  getTaskWiseBarChartData() {

    const labels = this.projectHours.map((p: any) => p.name);
    const estimated = this.projectHours.map((p: any) => p.assigned_tasks_count);
    const consumed = this.projectHours.map((p: any) => p.completed_tasks_count);

    const labelCount = this.projectHours.length;
    const minWidth = this.chartWrapper.nativeElement.offsetWidth || 600; // fallback
    const calculatedWidth = labelCount * 50;
    this.chartContainerWidth = Math.max(calculatedWidth, minWidth);

    this.vbarChartType = 'bar';
    this.vbarChartData = {
      labels: labels,
      datasets: [
        {
          label: 'Assigned Tasks',
          data: estimated,
          backgroundColor: 'rgba(54, 162, 235, 0.6)',
          hoverBackgroundColor: 'rgba(4, 92, 150, 0.6)'
        },
        {
          label: 'Completed Tasks',
          data: consumed,
          backgroundColor: 'rgba(255, 99, 132, 0.6)',
          hoverBackgroundColor: 'rgba(205, 8, 50, 0.6)',
        }
      ]
    }
    this.vbaroptions = {
      indexAxis: 'x',
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: {
          ticks: {
            autoSkip: false,
            maxRotation: 45,
            minRotation: 45
          }
        },
        y: {
          beginAtZero: true,
          //       ticks: {
          //   stepSize: 50
          // }
        }
      },
      plugins: {
        legend: {
          display: false
        }
      }
    };

  }

  getprojectAndTaskList() {
    const fromDate = this.datePipe.transform(this.dashBoardForm.controls.fromDate.value, 'yyyy-MM-dd');
    const toDate = this.datePipe.transform(this.dashBoardForm.controls.toDate.value, 'yyyy-MM-dd');
    const empid = this.userSession.id;
    this.timesheetService.getEmpoyeeTimesheetProjectsAndTasks(empid, fromDate, toDate).subscribe((res: any) => {
      if (res.data.length > 0) {
        this.projectNameList = res.data[0];
        this.tasktNameList = res.data[1];
      }

    })
  }

  getPendingTimesheetCount() {
    const fromDate = this.datePipe.transform(this.dashBoardForm.controls.fromDate.value, 'yyyy-MM-dd');
    const toDate = this.datePipe.transform(this.dashBoardForm.controls.toDate.value, 'yyyy-MM-dd');
    const empid = this.userSession.id;
    this.timesheetService.getEmpoyeePendingTimesheetsCount(empid, fromDate, toDate).subscribe((res: any) => {
      if (res.data.length > 0) {
        this.pendingCount = res.data[0].pending_timesheets_count;
         this.pendingDates = JSON.parse(res.data[0].pending_dates);
      }
    })
  }
openPendingPopup() {
  if (!this.pendingDates || this.pendingDates.length === 0) return;

  const dialogRef = this.dialog.open(PendingTimesheetPopupComponent, {
    width: '800px',
    data: { pendingDates: this.pendingDates }
  });

dialogRef.afterClosed().subscribe((result) => {
  console.log("AFTER CLOSED RESULT:", result);

  if (result) {
     let clicked = new Date(result.selectedDate);



      // ---- Fix Sunday issue & convert to Monday week ----

      const day = clicked.getDay(); // 0=Sun,1=Mon...



      // find Monday of the same week

      const monday = new Date(clicked);

      if (day === 0) {

        // Sunday → move forward to Monday

        monday.setDate(clicked.getDate() + 1);

      } else {

        // Other days → calculate Monday

        monday.setDate(clicked.getDate() - (day - 1));

      }



      const sunday = new Date(monday);

      sunday.setDate(monday.getDate() + 6);
    this.router.navigate(['timesheet/timesheet-entry'], {
      queryParams: {
        // selectedDate: result.selectedDate,
        // fromDate: result.firstDayOfWeek,
        // toDate: result.lastDayOfWeek,
        // tabIndex: 0
        selectedDate: this.datePipe.transform(clicked, 'yyyy-MM-dd'),

          fromDate: this.datePipe.transform(monday, 'yyyy-MM-dd'),

          toDate: this.datePipe.transform(sunday, 'yyyy-MM-dd'),

          tabIndex: 0
      }
    });
  }
});

}
}