loadEmployees() {
  const data = {
    rmid: this.userSession.empid,
    companyName: sessionStorage.getItem('companyName')
  };

  this.timesheetService.getTotalEmployeslistByManagerId(data).subscribe({
    next: (res: any) => {
      if (res.status) {
        this.employeesList = res.data || [];
        this.filteredEmployeesList = [...this.employeesList]; // initialize filter
      } else {
        this.employeesList = [];
        this.filteredEmployeesList = [];
      }
    },
    error: (err) => {
      console.error('Error fetching employees:', err);
    }
  });
}
onEmployeeSearch(event: Event) {
  const input = event.target as HTMLInputElement;
  this.filterEmployees(input.value);
}
filterEmployees(searchText: string) {
  this.employeeSearchText = searchText || '';
  const text = this.employeeSearchText.trim().toLowerCase();

  if (!text) {
    this.filteredEmployeesList = [...this.employeesList];
    return;
  }

  this.filteredEmployeesList = this.employeesList.filter(emp =>
    (emp.empname || '').toLowerCase().includes(text) ||
    (emp.empcode || '').toLowerCase().includes(text)
  );
}



