getApprovedHistory() {
  const empId = this.historyForm.controls.employeeId.value;
  const fromDate = this.historyForm.controls.fromDate.value;
  const toDate = this.historyForm.controls.toDate.value;

  console.log('Selected Employee ID:', empId);
  console.log('From Date:', fromDate);
  console.log('To Date:', toDate);

  // Prepare payload for API
  const payload = {
    rmid: this.userSession.id,
    emp_id: empId === 'all' ? 0 : empId,
    fromDate: this.datePipe.transform(fromDate, "y-MM-dd"),
    toDate: this.datePipe.transform(toDate, "y-MM-dd"),
  };

  console.log('Payload sent to API:', payload);

  // Call API
  this.timesheetService.getTimesheetHistory(payload).subscribe((res: any) => {
    console.log('API Response:', res);

    if (res.status && res.data && res.data.length > 0) {
      // Filter only Approved or Rejected records (case-insensitive, trimmed)
      const filteredData: any[] = res.data.filter((row: any) => {
        const status = row.submission_status?.toString().trim().toLowerCase();
        return status === 'approved' || status === 'rejected';
      });

      console.log('Filtered Data:', filteredData);

      this.List = filteredData;
      this.dataSource2 = new MatTableDataSource(filteredData);
      this.dataSource2.paginator = this.paginator2;
      this.dataSource2.sort = this.sort2;
      this.getPageSizes2();

    } else {
  this.List = [];  // ✅ CLEAR PDF DATA
  this.dataSource2 = new MatTableDataSource<any>([]);
}

  }, (error) => {
    console.error('API Error:', error);
    this.List = [];  // ✅ CLEAR PDF DATA
    this.dataSource2 = new MatTableDataSource<any>([]);
  });
}




