import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';

import { ExcelExportService } from 'src/app/services/excel-export.service';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
import { TimesheetService } from '../../timesheet.service';
@Component({
  selector: 'app-employee-project-details-dialog',
  templateUrl: './employee-project-details-dialog.component.html',
  styleUrls: ['./employee-project-details-dialog.component.scss']
})
export class EmployeeProjectDetailsDialogComponent implements OnInit {
  dataSource: any = [];
  displayedColumns: string[] = ['sno', 'date','description', 'submit_hours', 'cumulative', 'percentage', 'status'];

  inputData: any;
  projectId: any;
  managerid: any;
  taskid: any;
  employeeId: any;
  userSession: any;
  taskName: any;
  isTaskEnable: boolean = true;

  constructor(public dialogRef: MatDialogRef<EmployeeProjectDetailsDialogComponent>,
    private timesheetService: TimesheetService,
    private excelExportService: ExcelExportService,
    @Inject(MAT_DIALOG_DATA) public data: any,
    private pdfService: PdfHeaderService,) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getTaskEnbleOrDisableFlag();
    this.inputData = data.data;
    this.projectId = this.inputData.projectid;
    this.projectName = this.inputData.project;
    this.employeeId = this.userSession.id;
    this.taskid = this.inputData.task_id,
    this.taskName = this.inputData.taskname
  }
  arrayList: any = [];
  projectName: any;
  ngOnInit(): void {
    this.viewData();
  }

  getTaskEnbleOrDisableFlag() {
    this.timesheetService.getTimesheetTaskSelectionRuleValue().subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        let value = res.data[0].value;
       
        if (value == '0') {
          this.isTaskEnable = true
        } else {
          this.isTaskEnable = false;
        }
      }
    })
  }

  viewData() {
    
      this.arrayList = [];
      let data = {
        projectid: this.projectId,
        taskid: this.taskid,
        emp_id: this.employeeId
      }
      this.timesheetService.getTimesheetProjectsDetailedReportForEmployee(data).subscribe((res) => {
        if (res.status) {
          this.arrayList = res.data;
          this.dataSource = this.arrayList;
        } else {
          this.arrayList = [];
        }
      })

  }


  titleCase(str: string): string {
    return str.replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());
  }

  exportToExcel(): void {
    const columnsToRemove = ['id'];
    const dataToExport = this.arrayList.map((item: any, index: any) => {
      const newItem: any = {
        'S.No': index + 1
      };

      for (const key in item) {
        if (item.hasOwnProperty(key) && !columnsToRemove.includes(key)) {
          const titleCasedKey = this.titleCase(key);
          newItem[titleCasedKey] = item[key];
        }
      }
      return newItem;
    });

    this.excelExportService.exportAsExcelFile(dataToExport, 'Shift_Report');
  }

  generatePDF() {


    const doc = new jsPDF();
    const reportName = 'Shift Wise Employee Report';
    let manager = '';
    let locationName = '';
    let reportDate = '';
    const headerHeight = 33;
    const tableData = this.arrayList.map((emp: { shiftname: any; empname: any; status: any }, index: number) => [
      index + 1,
      emp.shiftname,
      emp.empname,
      emp.status,
    ]);
    autoTable(doc, {
      head: [['S.No.', 'Shift', 'Emp. Name', 'Status']],
      body: tableData,
      startY: headerHeight,
      styles: { fontSize: 10 },
      headStyles: { fontSize: 11 },
      margin: { top: headerHeight },
      didDrawPage: (data) => {
        this.pdfService.generatePDFHeader(doc, reportName, locationName, manager, reportDate, false, false);
        doc.setFontSize(10);
        doc.setTextColor(40);
      }
    });
    doc.save('Shiftwise_Employee_Report.pdf');
  }
}