import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, UntypedFormGroup } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { DatePipe } from '@angular/common';
import { TimesheetService } from '../../timesheet.service';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
import { MatDialog } from '@angular/material/dialog';
import * as XLSX from 'xlsx';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-variance-report',
  templateUrl: './variance-report.component.html',
  styleUrls: ['./variance-report.component.scss']
})
export class VarianceReportComponent implements OnInit {

  searchForm!: UntypedFormGroup;
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;

  isCustom: Boolean = false;
  userSession: any;
  statusList: string[] = [
    'Active',
    'Completed',
    'On Hold',
    'Cancelled'
  ];

  clientList: any = [];
  projectList: any = [];
  reportData: any = [];
  pageSizeOptions: number[] = [5, 10, 20];

  pipe = new DatePipe('en-US');
  displayedColumns: string[] = [
    'sno',
    'project',
    'pstartdate',
    'penddate',
    'phours',
    'ahours',
    'astartdate',
    'aenddate',
    'variance'
  ];
  List: any[] = [];
  is_super_admin: any = false;
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  constructor(private datePipe: DatePipe, private formBuilder: FormBuilder,
    private timesheetService: TimesheetService,
    private pdfService: PdfHeaderService,
    public dialog: MatDialog,
  ) {
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }

  selectedClientId: any;
  selectedProject: any = [];
  selectedClient: any = [];
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    if (this.userSession.is_super_admin == "1") {
      this.is_super_admin = true;
    }
    this.searchForm = this.formBuilder.group({
      client: [0],
      project: [0],
      fromDate: [new Date()],
      toDate: [new Date()],
      DateFormate: ['currentWeek'],
      status: ['Active'],
    });
    this.getTimesheetProjects();

    const today = new Date();
    let fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
    let toDate = new Date(today.setDate(today.getDate() - today.getDay()));
    this.searchForm.controls.fromDate.setValue(fromdate);
    this.searchForm.controls.toDate.setValue(new Date(toDate.setDate(toDate.getDate() + 6)));


    this.searchForm.get('project')?.valueChanges.subscribe((selectedValue: any) => {
      this.selectedProject = selectedValue;
      this.searchform(this.selectedProject);
    })
    this.searchform(0);

  }


  getTimesheetProjects() {
    this.timesheetService.getAllTimesheetProjects().subscribe((res: any) => {
      if (res.status) {
        this.projectList = res.data;
      } else {
        this.projectList = [];
      }
    });
  }

  searchform(id: any) {
    let projectId = id;
    this.List = [];
    this.timesheetService.getTimesheetEffortVarianceReportForManager(projectId).subscribe((res: any) => {
      if (res.status && res.data.length !== 0) {
        this.List = res.data;
        this.dataSource = new MatTableDataSource(this.List);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      } else {
        this.dataSource = new MatTableDataSource(this.List);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      }
    });
  }


  resetform() {
    this.ngOnInit();
  }



  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }
  
  getselectedProjectName(): string {

  const projectId = this.searchForm.get('project')?.value;



  if (!projectId || projectId === 0) {

    return 'All Projects';

  }



  const projectObj = this.projectList.find((p: { id: number; name: string }) => p.id === projectId);

  return projectObj ? projectObj.name : 'All Projects';

}

  generatePDF() {

    let selections = ``;
    selections = `Projects: ${this.getselectedProjectName()}`;
    
    let headers = ['S.No', 'Project', 'Start Date', 'End Date', 'Planned Hours', 'Actual Hours', 'Actual Start Date', 'Actual End Date', 'Variance'];
    let tblWidths: any = { 0: { cellWidth: 12 }, 1: { cellWidth: 45 }, 2: { cellWidth: 23 }, 3: { cellWidth: 23 }, 4: { cellWidth: 28 }, 5: { cellWidth: 30 }, 6: { cellWidth: 30 }, 7: { cellWidth: 30 }, 8: { cellWidth: 23 } };
    let tblBody: any = [
      ...this.List.map((row, index) => [
        index + 1,
        row.project ?? '',
        this.datePipe.transform(row.planned_start_date, "dd-MM-yyyy"),
        this.datePipe.transform(row.planned_end_date, "dd-MM-yyyy"),
        row.planned_hours,
        row.actual_hours,
        this.datePipe.transform(row.actual_start_date, "dd-MM-yyyy"),
        this.datePipe.transform(row.actual_end_date, "dd-MM-yyyy"),
        row.variance ?? '',
      ])];

    let tables = [{ headers: headers, sub_head: '', body: tblBody, widths: tblWidths, table_name: 'assignments' }];
    this.pdfService.generatePDF_common('landscape', 'Project Time Variance Report', selections, tables, 'variance_report.pdf');
  }
  

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  exportAsXLSX() {
    const exportData = this.List.map((row, index) => ({
      "S.No": index + 1,
      "Project": row.project,
      "Start Date": this.datePipe.transform(row.planned_start_date, "dd-MM-yyyy"),
      "End Date": this.datePipe.transform(row.planned_end_date, "dd-MM-yyyy"),
      "Planned Hours": row.planned_hours,
      "Actual Hours": row.actual_hours,
      "Actual Start Date": this.datePipe.transform(row.actual_start_date, "dd-MM-yyyy"),
      "Actual End Date": this.datePipe.transform(row.actual_end_date, "dd-MM-yyyy"),
      "Variance": row.variance,
    }));

    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);

    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Project Time Variance Report');

    /* save to file */
    XLSX.writeFile(wb,'project_time_variance_report.xlsx');
  }
}
