import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, FormControl, Validators, UntypedFormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { DatePipe } from '@angular/common';
import { TimesheetService } from '../../timesheet.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-task-master',
  templateUrl: './task-master.component.html',
  styleUrls: ['./task-master.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class TaskMasterComponent implements OnInit {

  taskMasterForm: any = UntypedFormGroup;
  taskData: any[] = [];
  editedTaskId: any = null;
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
  pageSizeOptions: number[] = [5, 10, 20];
  userSession: any;
  pipe = new DatePipe('en-US');
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  enable: any = null;
  valid: boolean = false;
  msgEM1: any;
  msgEM84: any;
  msgEM85: any;
  msgEM88: any;
  msgEM89: any;
  msgEM90: any
  msgEM91: any;
  msgEM92: any;
  msgEM151: any;
  msgEM152: any;
  todayDate: any = new Date();
  displayedColumns: string[] = ['sno', 'project', 'task', 'startDate', 'endDate', 'estimatedHours', 'status', 'Action'];
  companyClientsData: any = [];
  arrayValue: any = [
    { id: 'Active', value: 'Active' },
    { id: 'Inactive', value: 'Inactive' }
  ]
  dataSource: MatTableDataSource<any> = <any>[];
  pageLoading = true;

  messagesDataList: any = [];
  clientNameList: any[] = [];
  companyDBName: any;
  allActiveProjects: any[] = [];
  viewMode = false;
  isEditMode = false;
  projectForm: any;
  statusList: any = ['Not Started', 'In Progress', 'Completed'];
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  constructor(private formBuilder: UntypedFormBuilder,
    private router: Router,
    private snackbarService: CommonSnackbarService,
    private timesheetService: TimesheetService,) {
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();
  }

  projectSearchControl = new FormControl('');
  filteredProjects: any = [];
  ngOnInit(): void {

    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyDBName = sessionStorage.getItem("companyName")
    this.getTimesheetTasks();
    this.getAllActiveTimesheetProjects();
    this.taskMasterForm = this.formBuilder.group(
      {
        projectName: ["", [Validators.required]],
        taskName: ['', [Validators.required]],
        startDate: ['', [Validators.required]],
        endDate: ['', [Validators.required]],
        estimatedHours: ['', [Validators.required]],
        status: ['', Validators.required],
      },
    );
    this.projectSearchControl.valueChanges.subscribe(searchText => {
      this.filterProjects(searchText);
    });
    this.taskMasterForm.get('startDate')?.valueChanges.subscribe((startDate: any) => {
      // this.minToDate = selectedValue._d;
      if (!startDate) return;

      const start = startDate instanceof Date ? startDate : startDate._d ? startDate._d : new Date(startDate);
      this.minToDate = start;
      this.taskMasterForm.get('endDate')?.setValue(null);

    });


  }
  filterProjects(searchText: any) {
    this.filteredProjects = this.allActiveProjects.filter((val: any) =>
      val.project_name.toLowerCase().includes(searchText.toLowerCase())
    );
  }

  submit() {
    if (this.taskMasterForm.valid) {
      const taskPayload = {
        id_value: this.editedTaskId,
        project_id_value: this.taskMasterForm.value.projectName,
        taskname_value: this.taskMasterForm.value.taskName,
        start_date_value: this.pipe.transform(this.taskMasterForm.controls.startDate.value, 'yyyy-MM-dd'),
        end_date_value: this.pipe.transform(this.taskMasterForm.controls.endDate.value, 'yyyy-MM-dd'),
        task_hours_value: this.taskMasterForm.value.estimatedHours,
        task_status_value: this.taskMasterForm.value.status,
        created_by_value: this.userSession.id,
        updated_by_value: this.editedTaskId ? this.userSession.id : null,
      };
      this.timesheetService.setTimesheetTask(taskPayload).subscribe((res: any) => {

        if (res.status) {
          let value = res.data[0]
          if (value.statuscode == 0) {
            let message = this.isEditMode ? 'Data updated successfully' : 'Data saved successfully'
            this.snackbarService.show(message, true);

          } else if (value.statuscode == 1) {
            this.snackbarService.show("Record already exists", false);

          } else if (value.statuscode == 2) {
            this.snackbarService.show("Data updated successfully", true);
          }
          this.cancel()
        } else {

          this.snackbarService.show("Unable to save data", false);
        }
      });
    }
  }


  Add() {
    this.isAdd = true;
    this.isdata = false;
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/timesheet/task-master"]));
  }

  edit(event: any, row: any) {
    this.editedTaskId = row.id;
    this.isEditMode = true;
    this.isAdd = true;
    this.isSave = true;
    this.isdata = false;

    this.taskMasterForm.enable();

    this.taskMasterForm.patchValue({
      projectName: row.project_id,
      taskName: row.taskname,
      startDate: row.start_date,
      endDate: row.end_date,
      estimatedHours: parseInt(row.task_hours),
      status: row.task_status,
    });


  }


  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();

  }
  view(row: any) {
    this.viewMode = true;
    this.isEditMode = false;
    this.isAdd = true;

    this.taskMasterForm.patchValue({
      projectName: row.project_id,
      taskName: row.taskname,
      startDate: row.start_date,
      endDate: row.end_date,
      estimatedHours: row.task_hours,
      status: row.task_status
    });
    this.taskMasterForm.disable();
  }


  getTimesheetTasks() {
    this.timesheetService.getAllTimesheetTasks().subscribe((info: any) => {
      if (info.status && info.data.length != 0) {
        let data = info.data;
        this.dataSource = new MatTableDataSource(data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      }
    })
  }

  getAllActiveTimesheetProjects() {
    this.timesheetService.getAllActiveProjects().subscribe((info: any) => {
      if (info.status && info.data.length != 0) {
        this.allActiveProjects = info.data;
        this.filteredProjects = info.data;
      }
    })
  }

  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }

  /**Search functionality */
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

}
