import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { Router } from '@angular/router';

@Component({
  selector: 'app-pending-timesheet-popup',
  templateUrl: './pending-timesheet-popup.component.html',
  styleUrls: ['./pending-timesheet-popup.component.scss']
})
export class PendingTimesheetPopupComponent implements OnInit {

  pendingDates: any[] = [];

  constructor(
    public dialogRef: MatDialogRef<PendingTimesheetPopupComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any,
  ) {}


ngOnInit(): void {
  const rawDates = typeof this.data.pendingDates === 'string'
    ? JSON.parse(this.data.pendingDates)
    : this.data.pendingDates || [];

  this.pendingDates = rawDates.map((item: any) => {
    const key = Object.keys(item)[0];
    const value = item[key];
    return {
      dateObj: new Date(key),
      displayValue: value
    };
  });
}



  // Called when user clicks on a status
openTimesheet(date: any) {
  console.log("POPUP CLICKED DATE RAW:", date);

  const selectedDate = new Date(date);
  console.log("POPUP SELECTED DATE OBJECT:", selectedDate);

  const selected = new Date(selectedDate); 
  const day = selected.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat

  // Correct week calculation: Monday to Sunday including selected date
  const diffToMonday = day === 0 ? -6 : 1 - day;

  const firstDayOfWeek = new Date(selected);
  firstDayOfWeek.setDate(selected.getDate() + diffToMonday);

  const lastDayOfWeek = new Date(firstDayOfWeek);
  lastDayOfWeek.setDate(firstDayOfWeek.getDate() + 6);


  this.dialogRef.close({ 
    selectedDate, 
    firstDayOfWeek, 
    lastDayOfWeek 
  });
}


  

  castToString(val: any): string {
    return String(val);
  }
}
